parameters.jsCode:
// Split the cleaned book into overlapping chunks and record the pages each chunk covers
const CHUNK_SIZE = 2000; // characters per chunk
const OVERLAP = 200;     // characters repeated between two consecutive chunks
const MIN_LENGTH = 30;   // ignore blank pages and tiny leftovers

const { pages = [], source } = $input.first().json;

// Concatenate the pages and remember where each one starts in the full text
let fullText = '';
const pageStarts = [];
pages.forEach((page, index) => {
  if (page.length < MIN_LENGTH) return;
  pageStarts.push({ offset: fullText.length, pageNumber: index + 1 });
  fullText += page + '\n\n';
});
if (!pageStarts.length) {
  throw new Error('No extractable text in this PDF (scanned or image-only file?). Nothing was stored.');
}
const pageAt = (offset) => {
  let pageNumber = pageStarts[0].pageNumber;
  for (const start of pageStarts) {
    if (start.offset > offset) break;
    pageNumber = start.pageNumber;
  }
  return pageNumber;
};

const chunks = [];
let start = 0;
while (start < fullText.length) {
  let end = Math.min(start + CHUNK_SIZE, fullText.length);
  if (end < fullText.length) {
    // Prefer to cut at a paragraph, then a sentence, then a word boundary
    const window = fullText.slice(start, end);
    const cut = [window.lastIndexOf('\n\n'), window.lastIndexOf('. '), window.lastIndexOf(' ')]
      .find((position) => position > CHUNK_SIZE / 2);
    if (cut !== undefined) end = start + cut + 1;
  }
  const content = fullText.slice(start, end).trim();
  if (content.length >= MIN_LENGTH) {
    const firstPage = pageAt(start);
    const lastPage = pageAt(end - 1);
    chunks.push({
      json: {
        content,
        metadata: { source, pageNumber: firstPage === lastPage ? firstPage : `${firstPage}-${lastPage}`, chunkIndex: chunks.length },
      },
    });
  }
  if (end >= fullText.length) break;
  start = end - OVERLAP;
  const space = fullText.indexOf(' ', start); // do not start in the middle of a word
  if (space !== -1 && space < end) start = space + 1;
}
return chunks;

parameters.query:
insert into public.documents (content, metadata, embedding)
values ($1, $2::jsonb, $3::extensions.vector)
on conflict do nothing;

select coalesce(json_agg((metadata->>'chunkIndex')::int), '[]'::json) as stored
from public.documents
where metadata->>'source' = $1;

