// Skip the chunks already stored by a previous run: no duplicate rows and no wasted Gemini quota
const stored = new Set(($input.first().json.stored ?? []).map(Number));
return $('Limit').all().filter((chunk) => !stored.has(chunk.json.metadata.chunkIndex));

// Gather the question, the recent conversation and the settings used by the next steps
const config = $('Config').first().json;
const strip = (text) => String(text ?? '').replace(/[{}]/g, '').trim(); // braces break LangChain prompt templates

const lines = [];
for (const item of $input.all()) {
  const messages = Array.isArray(item.json.messages) ? item.json.messages : [item.json];
  for (const message of messages) {
    if (message.human) lines.push(`User: ${strip(message.human)}`);
    if (message.ai) lines.push(`Assistant: ${strip(message.ai)}`);
    const role = message.type ?? message.role;
    const text = message.content ?? message.text ?? message.data?.content ?? message.kwargs?.content;
    if (!message.human && !message.ai && role && text) {
      lines.push(`${/ai|assistant/i.test(role) ? 'Assistant' : 'User'}: ${strip(text)}`);
    }
  }
}

return [{
  json: {
    question: strip(config.chatInput),
    history: lines.slice(-2 * config.historyExchanges).join('\n') || 'No previous messages.',
    config,
  },
}];

// One item per search query (at most maxQueries), each carrying the keywords for the full-text part of the search
const { config, question } = $('Context').first().json;
const routing = $input.first().json.output ?? {};

const queries = [...new Set((routing.queries ?? []).map((query) => String(query).trim()).filter(Boolean))].slice(0, config.maxQueries);
if (!queries.length) queries.push(routing.standaloneQuestion || question);

// websearch_to_tsquery syntax: multi-word keywords between quotes, joined with "or"
const keywords = (routing.keywords ?? [])
  .map((keyword) => String(keyword).replace(/["']/g, '').trim())
  .filter(Boolean)
  .map((keyword) => (keyword.includes(' ') ? `"${keyword}"` : keyword))
  .join(' or ');

return queries.map((query) => ({ json: { query, keywords } }));

// Merge the results of all queries: one entry per chunk with its best score, best candidates first
const { config, question } = $('Context').first().json;
const routing = $('Routing').first().json.output ?? {};

const best = new Map();
for (const { json: row } of $input.all()) {
  if (!row.id) continue;
  const key = String(row.id);
  if (!best.has(key) || Number(row.score) > Number(best.get(key).score)) best.set(key, row);
}

const candidates = [...best.values()]
  .sort((a, b) => Number(b.score) - Number(a.score))
  .slice(0, config.candidateCount)
  .map((row) => ({
    id: Number(row.id),
    page: row.metadata?.pageNumber,
    source: row.metadata?.source,
    content: String(row.content ?? '').replace(/[{}]/g, ''),
  }));

const candidateList = candidates
  .map((candidate) => `<passage id="${candidate.id}" page="${candidate.page}">\n${candidate.content}\n</passage>`)
  .join('\n\n');

return [{ json: { question: routing.standaloneQuestion || question, candidates, candidateList: candidateList || 'NO PASSAGE FOUND' } }];

// Keep the passages Gemini judged most relevant and format them as cited excerpts for the answer
const { config } = $('Context').first().json;
const { question, candidates } = $('Merge Results').first().json;
const relevance = new Map(($input.first().json.output?.ranking ?? []).map((entry) => [Number(entry.id), Number(entry.score)]));

const kept = candidates
  .map((candidate) => ({ ...candidate, relevance: relevance.get(candidate.id) ?? 0 }))
  .filter((candidate) => candidate.relevance >= config.minRerankScore)
  .sort((a, b) => b.relevance - a.relevance)
  .slice(0, config.keepCount);

const context = kept
  .map((passage, index) => `<excerpt id="${index + 1}" source="${passage.source || 'reference book'}" page="${passage.page || 'unknown'}">\n${passage.content}\n</excerpt>`)
  .join('\n\n');

return [{ json: { question, context: context || 'NO RELEVANT EXCERPT FOUND' } }];

